s += """\n\n/* Performance capture */\n.perf-log-controls {\n  display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-top: 9px;\n  padding: 8px; border: 1px solid rgba(139,215,169,.13); border-radius: 9px; background: rgba(139,215,169,.035);\n}\n.perf-log-controls .dev-tuning-action:disabled { opacity: .42; cursor: default; }\n.perf-log-state { color: #8fa99b; font-size: 10px; font-variant-numeric: tabular-nums; }\n.perf-log-state.is-recording { color: #8bd7a9; }\n.perf-log-state.is-recording::before { content: '● '; color: #e26d63; }\n.dev-tuning-head .dev-fps-value { margin-left: 6px; max-width: 330px; overflow: hidden; text-overflow: ellipsis; }\n"""
